        function CheckSign(strValues, gridValues) {
            
            var losesign = false;
            if ($('#hSignType').val() == "0"    $('#hClearSign').val() == "0") 
                return losesign;
            
            var sendObj = {};
            sendObj.IidPlus = $("#hIidPlus").val(); 
            sendObj.fid = $("#hfid").val(); 
            sendObj.input_index = RealInputIdx();
            sendObj.strElements = encodeURIComponent(strValues);
            sendObj.gridElements = encodeURIComponent(gridValues);
            sendObj.acttype = "SignCheck";
            $.ajax({
                type: "POST",
                async: false,
                cache: false,
                url: '../appservice/HtmlMainPageHandle.ashx',
                data: eval(sendObj),
                dataType: 'text',
                error: function(XMLHttpRequest, textStatus, errorThrown) {
                    if (showMsg)
                        showMsgBox(JSON.stringify(errorThrown), true);
                },
                success: function(result) {
                    if (result != "0") {
                        losesign = true;
                    }
                }
            });
            return losesign;
        }

